/* Shared foundation appearance. Reports are owned by core/reports.js. */
(function(){
  function apply(){
    document.documentElement.setAttribute('data-pn-foundation','v02');
    const oldChip=document.getElementById('pn-foundation-chip'); if(oldChip) oldChip.remove();
    const ticker=document.getElementById('stock-ticker'); if(ticker) ticker.classList.remove('visible');
    const footer=document.querySelector('#home-statbar'); if(footer) footer.style.display='none';
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply);else apply();
  setTimeout(apply,300);setTimeout(apply,1400);
  function injectReportStyles(){
    if(document.getElementById('ops-report-v1-style'))return;
    var style=document.createElement('style');
    style.id='ops-report-v1-style';
    style.textContent=`
.operations-report-modal{width:min(940px,96vw)!important;max-height:90vh!important;overflow:auto!important;border-color:rgba(185,148,255,.28)!important;box-shadow:0 30px 100px rgba(0,0,0,.72),0 0 50px rgba(139,92,246,.11)!important}
.ops-report-shell{font-family:'Plus Jakarta Sans',sans-serif;color:var(--text);min-height:100%}.ops-report-header{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;padding:24px 28px 20px;border-bottom:1px solid rgba(185,148,255,.16);background:radial-gradient(circle at 12% 0,rgba(139,92,246,.14),transparent 42%),linear-gradient(110deg,rgba(167,137,255,.055),rgba(139,92,246,.055));position:sticky;top:0;z-index:4;backdrop-filter:blur(12px)}
.ops-report-kicker{font-size:10.2px;font-weight:800;letter-spacing:2.8px;color:#ffffff;margin-bottom:6px}.ops-report-title{font-family:'Bebas Neue',sans-serif;font-size:33.9px;letter-spacing:2px;line-height:1;color:#ffffff}.ops-report-subtitle{font-size:11.3px;color:var(--muted2);margin-top:7px}.ops-report-close{font-size:28.2px;padding:0 2px}.ops-report-body{padding:22px 28px 26px}.ops-report-section{margin-bottom:22px}.ops-report-section-title{font-size:10.2px;font-weight:800;letter-spacing:2px;text-transform:uppercase;color:#aebed0;margin-bottom:9px}.ops-report-grid{display:grid;gap:9px}.ops-report-grid-4{grid-template-columns:repeat(4,minmax(0,1fr))}
.ops-report-metric{min-width:0;padding:13px 14px;border:1px solid rgba(125,238,255,.11);border-radius:9px;background:linear-gradient(180deg,rgba(255,255,255,.035),rgba(255,255,255,.014))}.ops-report-metric.positive{border-color:rgba(78,234,170,.18)}.ops-report-metric.negative{border-color:rgba(244,63,94,.26);background:rgba(244,63,94,.045)}.ops-report-metric.expense{border-color:rgba(255,207,90,.16)}.ops-report-metric-label{font-size:9.6px;letter-spacing:1.2px;text-transform:uppercase;color:var(--muted2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.ops-report-metric-value{font-family:'DM Mono',monospace;font-size:20.3px;font-weight:700;color:#edf7ff;margin-top:6px;white-space:nowrap}.ops-report-metric.positive .ops-report-metric-value{color:var(--profit)}.ops-report-metric.negative .ops-report-metric-value{color:var(--loss)}.ops-report-metric.expense .ops-report-metric-value{color:var(--warn)}.ops-report-metric-note{font-size:9.6px;color:var(--muted2);margin-top:4px}
.ops-report-route-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.ops-report-route{display:flex;flex-direction:column;gap:5px;padding:14px 16px;border-radius:9px;border:1px solid rgba(125,238,255,.12);background:rgba(255,255,255,.022)}.ops-report-route.best{border-color:rgba(78,234,170,.22);background:rgba(78,234,170,.035)}.ops-report-route.warning{border-color:rgba(255,207,90,.24);background:rgba(255,207,90,.035)}.ops-report-route-tag{font-size:9px;font-weight:800;letter-spacing:1.5px;color:var(--muted2)}.ops-report-route strong{font-size:13.6px;color:var(--text)}.ops-report-route span:last-child{font-family:'DM Mono';font-size:10.2px;color:var(--muted)}
.ops-report-alerts{display:flex;flex-direction:column;gap:7px}.ops-report-alert{display:flex;gap:10px;align-items:flex-start;padding:10px 12px;border-radius:8px;border:1px solid rgba(125,238,255,.10);background:rgba(255,255,255,.018)}.ops-report-alert-icon{width:22px;height:22px;display:grid;place-items:center;border-radius:6px;background:rgba(125,238,255,.07);color:#fff;font-weight:800;flex:0 0 auto}.ops-report-alert b{display:block;font-size:11.3px;color:var(--text);margin-bottom:2px}.ops-report-alert div span{display:block;font-size:10.2px;line-height:1.45;color:var(--muted2)}.ops-report-alert.warn{border-color:rgba(255,207,90,.18)}.ops-report-alert.warn .ops-report-alert-icon{background:rgba(255,207,90,.08);color:var(--warn)}.ops-report-alert.danger{border-color:rgba(244,63,94,.22)}.ops-report-alert.danger .ops-report-alert-icon{background:rgba(244,63,94,.09);color:var(--loss)}.ops-report-alert.good{border-color:rgba(78,234,170,.18)}.ops-report-alert.good .ops-report-alert-icon{background:rgba(78,234,170,.08);color:var(--profit)}
.ops-report-footer{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-top:6px;padding-top:16px;border-top:1px solid rgba(125,238,255,.10)}.ops-report-skip{display:flex;align-items:center;gap:8px;font-size:10.2px;color:var(--muted2);cursor:pointer}.ops-report-skip input{accent-color:#a78bfa}.ops-report-continue{border:1px solid rgba(185,148,255,.48);border-radius:8px;padding:10px 17px;background:linear-gradient(135deg,rgba(139,92,246,.24),rgba(167,137,255,.10));color:#ffffff;font:700 11.3px 'Plus Jakarta Sans';letter-spacing:.8px;text-transform:uppercase;cursor:pointer;box-shadow:0 8px 24px rgba(76,29,149,.18)}.ops-report-continue:hover{border-color:#c4a7ff;background:linear-gradient(135deg,rgba(139,92,246,.34),rgba(167,137,255,.15))}.ops-report-continue span{font-size:16.9px;margin-left:7px;vertical-align:-1px}@media(max-width:760px){.ops-report-grid-4{grid-template-columns:repeat(2,minmax(0,1fr))}.ops-report-route-grid{grid-template-columns:1fr}.ops-report-header,.ops-report-body{padding-left:18px;padding-right:18px}.ops-report-footer{align-items:flex-start;flex-direction:column}.ops-report-continue{width:100%}}`;
    document.head.appendChild(style);
  }
  injectReportStyles();
})();
